// Omniflow batch 1331 - ENGINE 8: POLICY/RULE HUB (shared evaluator +
// unified rule audit + the portal Rules page). Unify, not duplicate:
// portal_policy (NEW) adds the shared condition evaluator (whole-word
// keyword ops, all/any groups, safe defaults), the policy.<set>.fired
// unified audit line, and a fail-soft rules summary of all 7 families
// (routing/listen/negotiation/hours/handoff/autonomy/approvals) with
// deep links. Routing + listen now also write the unified audit.
// Web: 2 BFF routes, the light /dashboard/rules page (family cards +
// a save-nothing rule tester), sidebar entry. Rig: test_policy.py
// (32 checks). Whole-file marker-guarded ops (backup on drift,
// .pre_policy.bak); idempotent; dir-conflicts quarantined.
import fs from "fs";
const BACKUP_TAG = ".pre_policy.bak";
let applied = 0, already = 0, warnings = 0;
function writeNewRepair(repoPath, marker, isCp, content) {
  try {
  let existed = false;
  if (fs.existsSync(repoPath)) {
    if (fs.statSync(repoPath).isDirectory()) {
      let target = repoPath + ".dir_conflict.bak";
      let n = 1;
      while (fs.existsSync(target)) { target = repoPath + ".dir_conflict.bak." + n; n++; }
      fs.renameSync(repoPath, target);
      console.log("! " + repoPath + " was a DIRECTORY - renamed to " + target + "; writing the real file.");
      warnings++;
    } else existed = true;
  }
  if (!existed) {
    const cut = Math.max(repoPath.lastIndexOf("/"), repoPath.lastIndexOf("\\"));
    if (cut > 0) fs.mkdirSync(repoPath.slice(0, cut), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    console.log("+ " + repoPath + " (restored - was missing)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already correct)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  fs.writeFileSync(repoPath, content, "utf8");
  console.log("+ " + repoPath + " (REPAIRED - old copy kept as " + BACKUP_TAG + ")");
  applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED: " + err.message);
    warnings++;
  }
}
